[meta]
name = The Harrow Sewers
ambient = 0.2 0.22 0.17
fog = 0.045 0.06 0.045
fog_range = 4 22
torch = 9 0.72 0.7 0.52
start = 2 3 90
default = .
entity_floor = auto
edge_top = 6
edge_tex = sewer_brick

// The sewers under Harrowmere: four grates in the town's corners drop into four districts, all joined
// through the old cistern at the heart of them, so each way down is a short way back to the others.
// The North Sluices under the cathedral's terrace, with the gate machinery of the sluice channel, a
// long drain running east from them to the grate by the Vesper Gate; the Market Drains, narrow vaulted
// runs under the west side's lanes, reached down a drain from the grate in the north-west corner; the
// Canal Culvert under the sea wall, where the old canal ran before the town was walled in; and the
// Quay Outfall, where the sewers pour out through great grates into the sea. Between the cistern and
// the outfall Mother Gnawl, the rats' brood-mother, keeps her nest; below the outfall a stair goes down
// to the Sump, and behind its door the Sodden Pall, all the drains ever carried grown a skin (a bell of
// green ooze twice a man's height, a drowned face in its folds), fills the deepest cistern; with it gone,
// the breach in the cistern's north wall leads down into Old Harrowmere. Wadeable sludge (slow
// going) fills the gutters; the clearer channels cast you back out.

[legend]
# = wall tex=sewer_brick top=6
// The shafts the ladders climb up to the street grates, and the walls round them, as tall.
% = wall tex=sewer_brick top=11
^ = floor tex=flagstone h=0 ceil=11 ceil_tex=sewer_vault side=sewer_brick
. = floor tex=flagstone h=0 ceil=3.4 ceil_tex=sewer_vault side=sewer_brick
d = floor tex=flagstone h=0 ceil=3.4 ceil_tex=sewer_vault side=sewer_brick dark=0.5
, = floor tex=flagstone h=0 ceil=6 ceil_tex=sewer_vault side=sewer_brick
- = floor tex=sludge h=-0.4 ceil=3.4 ceil_tex=sewer_vault side=sewer_brick slow=0.6
s = floor tex=sludge h=-0.4 ceil=3.4 ceil_tex=sewer_vault side=sewer_brick slow=0.6 dark=0.5
= = floor tex=sludge h=-0.4 ceil=3.4 ceil_tex=sewer_vault side=sewer_brick slow=0.6 flow=0.7,0
~ = water tex=bog h=-0.9 ceil=3.4 ceil_tex=sewer_vault side=sewer_brick
w = water tex=bog h=-0.9 ceil=6 ceil_tex=sewer_vault side=sewer_brick
_ = floor tex=sludge h=-6 ceil=3.4 ceil_tex=sewer_vault side=sewer_brick chasm
| = floor tex=flagstone h=-8 ceil=3.4 ceil_tex=sewer_vault side=sewer_brick chasm
n = floor tex=dirt h=0 ceil=4 ceil_tex=sewer_vault side=sewer_brick dark=0.35
