[entities]
// The four ladders up to the town's grates, each under the grate it climbs to.
A = exit map=harrowmere at=44,2,180 label=Climb_up_by_the_Vesper_Gate model=sewer_ladder on=^ yaw=180
B = exit map=harrowmere at=3,2,0 label=Climb_up_by_the_north_road model=sewer_ladder on=^ yaw=90
C = exit map=harrowmere at=4,37,0 label=Climb_up_by_the_sea_wall model=sewer_ladder on=^ yaw=-90
D = exit map=harrowmere at=44,39,180 label=Climb_up_by_the_east_wall model=sewer_ladder on=^ yaw=180
// The cistern's shrine, its pillars and the light.
E = save_statue
F = torch radius=8
G = sump_caps radius=4
P = pillar
// What lives down here: rats in packs and a few as big as hounds, sludge that crawls, the drowned lying
// in the muck and leeches in the gutters by the channels.
H = sewer_rat
I = giant_rat
J = sludge_slime
K = drowned on=-
Ò = drowned on=p
Ó = drowned on=k
L = bilge_leech on==
Ô = bilge_leech on=-
Õ = bilge_leech on=p
Ö = bilge_leech on=k
// Mother Gnawl in her nest between the cistern and the outfall, and the Sodden Pall behind its door.
M = rat_matron
N = sodden_pall
O = door boss=pall_dead
// Behind it, the breach the Pall's weight wore through the cistern's north wall: down into Old Harrowmere.
Ñ = exit map=old_harrowmere at=3,3,0 label=Descend_into_Old_Harrowmere model=cistern_breach yaw=90 requires=pall_dead shut="Rubble chokes the breach. Something vast still stirs in the cistern." on=v
// Her nest has a great door at each mouth: die in there and both give way to fog.
Ù = door boss=matron_dead
// Finds: ailments' remedies mostly, for the sewers breed them all.
Q = chest item=bitter_root count=2 gold=40 model=worn
R = chest item=clotting_salve count=2 gold=60 model=worn
S = chest item=grave_lily gold=80
T = chest item=menders_kit gold=50 model=coffer
U = chest item=red_tonic count=2 gold=70 model=worn
V = chest item=blue_moss count=2 gold=120 model=banded
W = secret_wall
// Shortcuts: the short way down from the sluices, barred on their side; the drawbridge over the sluice
// pit between the culvert and the outfall, let down from the outfall's side; and the lift from the Sump
// up to the cistern, fastened up there until you first ride it.
X = door from=n
Y = lever id=sluice_bridge
Z = bridge lever=sluice_bridge hinge=e deck=0 on=_
À = lift top=0 locked on=|
